INSERT OR IGNORE INTO `rater_email_templates` (`template_key`,`name`,`subject`,`preheader`,`heading`,`body_html`,`button_label`,`brand_primary`,`brand_accent`,`updated_at`) VALUES
('rater_invite','Initial rater invitation','{{candidate_name}} invited you to provide 360 feedback','Your private OrgInsights feedback link is ready.','Share what you have observed','<p>Hi {{rater_name}},</p><p>{{candidate_name}} has invited you to provide private 360 feedback through OrgInsights.</p><p>Please answer based on the behaviour you have personally observed. Your unique link does not require a login.</p>','Give feedback','#075d46','#a9ddc5',(unixepoch('now') * 1000)),
('rater_reminder_1','Rater reminder 1','Reminder: feedback for {{candidate_name}}','Your private feedback link is still open.','Your perspective is still needed','<p>Hi {{rater_name}},</p><p>This is a reminder to complete the OrgInsights 360 feedback requested by {{candidate_name}}.</p><p>Your unique link is still active. Please answer from your direct experience.</p>','Continue feedback','#075d46','#a9ddc5',(unixepoch('now') * 1000)),
('rater_reminder_2','Rater reminder 2','Please complete your feedback for {{candidate_name}}','A short reminder from OrgInsights.','Help complete the 360 view','<p>Hi {{rater_name}},</p><p>{{candidate_name}} is still waiting for your 360 feedback.</p><p>Please use your private link when you have a focused moment. You can return to saved answers until you submit.</p>','Resume feedback','#075d46','#a9ddc5',(unixepoch('now') * 1000)),
('rater_reminder_3','Ongoing rater reminder','Your 360 feedback link for {{candidate_name}} is still open','Complete the feedback requested by your colleague.','One more reminder','<p>Hi {{rater_name}},</p><p>Your OrgInsights feedback request from {{candidate_name}} remains open.</p><p>Reminders stop as soon as you submit or the candidate closes the 360 assessment.</p>','Complete feedback','#075d46','#a9ddc5',(unixepoch('now') * 1000));